class NuevaSerie(BaseModel):
    nombre: str
    instructor: str
    dia: Dia
    hora: str = Field(pattern=HORA)
    duracion_min: StrictInt = Field(ge=1)
    cupo: StrictInt = Field(ge=1)
    desde: date
    hasta: date

    @field_validator('nombre', 'instructor')
    @classmethod
    def no_vacio(cls, valor: str) -> str:
        return sin_vacio(valor)

    @model_validator(mode='after')
    def fechas_en_orden(self):
        dias = (self.hasta - self.desde).days
        if dias < 0:
            raise ValueError('hasta es anterior a desde')
        if dias > 366:
            raise ValueError('la serie no puede durar más de 366 días')
        return self


def inicios_de_la_serie(datos: NuevaSerie, ahora):
    """Inicio de cada clase de la serie: en cada día del `dia` entre desde y hasta, salvo cierres y pasados."""
    inicios = []
    dia = datos.desde
    while dia <= datos.hasta:
        if dia.weekday() == DIAS.index(datos.dia) and dia not in DIAS_CERRADOS:
            inicio = hora_en_dia(dia, datos.hora)
            if inicio > ahora:
                inicios.append(inicio)
        dia += timedelta(days=1)
    return inicios


