import os
from datetime import date, datetime, time, timedelta
from typing import Literal, get_args

from fastapi import APIRouter, Depends, FastAPI, Header, HTTPException
from pydantic import (AwareDatetime, BaseModel, Field, StrictInt, field_validator, model_validator)

from pulso import correo, db, reloj

router = APIRouter()

Dia = Literal['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo']
DIAS = get_args(Dia)  # índice = date.weekday()
HORA = r'^(?:[01][0-9]|2[0-3]):[0-5][0-9]$'
# Días en que cierra el gimnasio: la serie no tiene clase esas semanas.
DIAS_CERRADOS = {date(2026, 12, 25), date(2027, 1, 1), date(2027, 2, 8), date(2027, 2, 9),
                 date(2027, 3, 25), date(2027, 3, 26), date(2027, 5, 1)}


def socio_actual(authorization: str | None = Header(default=None)):
    if not authorization or not authorization.startswith('Bearer '):
        raise HTTPException(401, 'Falta el token')
    socio = db.socio_por_token(authorization.removeprefix('Bearer '))
    if socio is None:
        raise HTTPException(401, 'Token inválido')
    return socio


def admin(x_admin_key: str | None = Header(default=None)):
    if not x_admin_key or x_admin_key != os.environ.get('PULSO_ADMIN_KEY'):
        raise HTTPException(401, 'Clave de administración inválida')


def ver_clase(clase):
    return dict(clase, lugares_libres=clase['cupo'] - db.confirmadas(clase['id']))


def ver_reserva(reserva):
    return {k: reserva[k] for k in ('id', 'clase_id', 'estado', 'creada')}


def ver_serie(serie):
    clases = db.clases_de_serie(serie['id'])
    return {
        'id': serie['id'], 'nombre': serie['nombre'], 'instructor': serie['instructor'], 'dia': serie['dia'],
        'hora': serie['hora'], 'duracion_min': serie['duracion_min'], 'cupo': serie['cupo'],
        'desde': serie['desde'], 'hasta': serie['hasta'], 'clases': [ver_clase(c) for c in clases],
    }


def hora_en_dia(dia_local, hora):
    """Momento de `hora` (HH:MM) en el día `dia_local`, en hora de Montevideo."""
    horas, minutos = map(int, hora.split(':'))
    return datetime.combine(dia_local, time(horas, minutos), tzinfo=reloj.MONTEVIDEO)


